const input = $input.first().json;
const data = input.body || input;

const allInputs = $input.all();
console.log('✅ Agent 2: Received', allInputs.length, 'item(s)');

if (allInputs.length !== 1) {
  console.error('⚠️ AGENT 2 ERROR: Expected 1 item, got', allInputs.length);
}

const searchQuery = data.topic || 'AI trends';

return [{
  json: {
    topic: data.topic,
    url: data.url || '',
    style: data.style,
    length: data.length,
    angle: data.angle,
    searchQuery: searchQuery
  }
}];

const inputData = $input.first().json;
const serpResults = inputData.organic_results || [];

const sources = [];
const snippets = [];

for (let i = 0; i < Math.min(serpResults.length, 5); i++) {
  const result = serpResults[i];
  if (result.link && result.title) {
    sources.push({
      url: result.link,
      title: result.title
    });
  }
  if (result.snippet) {
    snippets.push(result.snippet);
  }
}

const prepData = $("Parse Input").first().json;

const researchSummary = `Research on: ${prepData.topic}\n\nKey findings:\n${snippets.join('\n\n')}`;

return [{
  json: {
    researchSummary: researchSummary,
    sources: sources,
    topic: prepData.topic,
    style: prepData.style,
    length: prepData.length,
    angle: prepData.angle
  }
}];
